  values ((select a.id from public.assessments a join public.learning_units u on u.id = a.unit_id where u.release_id = v_release_id and u.source_key = '12_Station_2.6_Panic_Disorder_and_Explaining_CBT' and a.source_key = 'exam'), (select id from public.question_kinds where key = 'single_choice'), 'q-1', 1, true, 'the fear taken seriously', '2 · Dai, and the Sunday five years ago. How does the family history get handled?', 'The critical decision, and the reason this patient is harder than Leila. His belief is not a distortion pulled out of nowhere; he watched his brother die at forty-four and he is forty-one, and any human being would think what he thinks. Saying so out loud is what buys the right to say anything else. Note the second half: a real family history deserves a real answer — his risk assessed properly and once, with a date and a person — which is a different thing entirely from repeated reassurance. Putting the death in proportion before it has been asked about is arguing with him; filing it as ‘the precipitant’ turns a bereavement into a mechanism.')
  on conflict (assessment_id, source_key) do nothing;
  insert into public.answer_options (question_id, source_key, sort_order, option_text, feedback)
  values ((select q.id from public.assessment_questions q join public.assessments a on a.id = q.assessment_id join public.learning_units u on u.id = a.unit_id where u.release_id = v_release_id and u.source_key = '12_Station_2.6_Panic_Disorder_and_Explaining_CBT' and a.source_key = 'exam' and q.source_key = 'q-1'), 'option-0', 0, 'Asked about properly, and named as making the fear reasonable — with his own cardiovascular risk to be answered factually, once, rather than waved away.', null)
  on conflict (question_id, source_key) do nothing;
