  values ((select a.id from public.assessments a join public.learning_units u on u.id = a.unit_id where u.release_id = v_release_id and u.source_key = '12_Station_2.6_Panic_Disorder_and_Explaining_CBT' and a.source_key = 'exam'), (select id from public.question_kinds where key = 'single_choice'), 'q-4', 4, false, null, '5 · He sits back: “So you’re telling me it’s all in my head.”', 'The sentence every explanation in psychiatry eventually meets, and it is answered by a distinction rather than a denial: the racing heart is real, the tightness is real, the numb hands are real — all produced by an alarm system doing precisely what it evolved to do. What is wrong is not the sensation but the conclusion drawn from it. The bare denial reassures without informing and leaves him with nothing to hold. And the frank ‘yes, in a sense’ hands him the word he came in braced for, at the exact moment he is deciding whether this doctor is like the others.')
  on conflict (assessment_id, source_key) do nothing;
  insert into public.answer_options (question_id, source_key, sort_order, option_text, feedback)
