  on conflict (assessment_id, source_key) do nothing;
  insert into public.answer_options (question_id, source_key, sort_order, option_text, feedback)
  values ((select q.id from public.assessment_questions q join public.assessments a on a.id = q.assessment_id join public.learning_units u on u.id = a.unit_id where u.release_id = v_release_id and u.source_key = '30_Station_4.9_PTSD_Assessment' and a.source_key = 'exam' and q.source_key = 'q-0'), 'option-0', 0, 'Answers the fear honestly — that is what today will settle, it is settled by describing the experiences rather than the robbery, and he can stop.', null)
