  insert into public.assessment_questions (assessment_id, question_kind_id, source_key, sort_order, is_critical, critical_label, stem, explanation)
  values ((select a.id from public.assessments a join public.learning_units u on u.id = a.unit_id where u.release_id = v_release_id and u.source_key = '45_Station_7.2_The_Angry_Father' and a.source_key = 'exam'), (select id from public.question_kinds where key = 'single_choice'), 'q-2', 2, false, null, '3 · Quieter, suddenly: “I sat opposite her every night. Every night — and I didn’t see it coming back. What kind of husband misses that?” What does the next minute do?', 'The fear underneath, surfaced — this station’s Neil. It gets received fully, answered honestly — relapse often shows nothing from the sofa; the medication stopped quietly, and quietly is how it goes — and then connected out loud: this is why the letter is shaking, why the missed call is unbearable — because the ward’s silence and his own ‘missing it’ have fused into one guilt. The quick absolution — ‘nobody could have known’ — is hollow and he’ll hear it; worse, it’s not quite true, and he knows that too. And ‘refocus on the plan’ sets down the key he just handed you. Honour it, connect it, then move — in that order.')
  on conflict (assessment_id, source_key) do nothing;
  insert into public.answer_options (question_id, source_key, sort_order, option_text, feedback)
  values ((select q.id from public.assessment_questions q join public.assessments a on a.id = q.assessment_id join public.learning_units u on u.id = a.unit_id where u.release_id = v_release_id and u.source_key = '45_Station_7.2_The_Angry_Father' and a.source_key = 'exam' and q.source_key = 'q-2'), 'option-0', 0, 'Receive it and answer it honestly — relapse can be invisible from the sofa; his watching was love, not failure — and connect it to today’s fury.', null)
  on conflict (question_id, source_key) do nothing;
  insert into public.answer_options (question_id, source_key, sort_order, option_text, feedback)
