  values ((select q.id from public.assessment_questions q join public.assessments a on a.id = q.assessment_id join public.learning_units u on u.id = a.unit_id where u.release_id = v_release_id and u.source_key = '45_Station_7.2_The_Angry_Father' and a.source_key = 'exam' and q.source_key = 'q-3'), 'option-0', 0, 'Own it precisely — the missed call named as the ward’s failure, apologised for unhedged, with exactly what changes and how it’s being reported.', null)
  on conflict (question_id, source_key) do nothing;
  insert into public.answer_options (question_id, source_key, sort_order, option_text, feedback)
