  insert into public.assessment_questions (assessment_id, question_kind_id, source_key, sort_order, is_critical, critical_label, stem, explanation)
  values ((select a.id from public.assessments a join public.learning_units u on u.id = a.unit_id where u.release_id = v_release_id and u.source_key = '45_Station_7.2_The_Angry_Father' and a.source_key = 'exam'), (select id from public.question_kinds where key = 'single_choice'), 'q-4', 4, false, null, '5 · “She doesn’t leave this ward again until you can promise me — promise me — this never happens again.” What can honesty give him?', 'The hard line held warmly, in this station’s weather: no false promise — relapse cannot be promised away, and he has already watched one written promise fail — but the promisable given fully and concretely: a named person, a follow-up call he can set his watch by, his observations built into the plan, the early-warning signs shared with Noreen’s agreement. The personal guarantee feels generous and forges the next broken letter — staking your name on the unpromisable is how trust dies twice. And the correction — ‘not a negotiation’ — answers a terrified man’s plea with governance. Say what is yours to give; give all of it; and let the honesty about the rest be part of the gift.')
  on conflict (assessment_id, source_key) do nothing;
  insert into public.answer_options (question_id, source_key, sort_order, option_text, feedback)
  values ((select q.id from public.assessment_questions q join public.assessments a on a.id = q.assessment_id join public.learning_units u on u.id = a.unit_id where u.release_id = v_release_id and u.source_key = '45_Station_7.2_The_Angry_Father' and a.source_key = 'exam' and q.source_key = 'q-4'), 'option-0', 0, 'What can actually be promised — the named contact, the follow-up that will happen, the plan he’ll help build — and honesty about what can’t be.', null)
  on conflict (question_id, source_key) do nothing;
  insert into public.answer_options (question_id, source_key, sort_order, option_text, feedback)
