  values ((select q.id from public.assessment_questions q join public.assessments a on a.id = q.assessment_id join public.learning_units u on u.id = a.unit_id where u.release_id = v_release_id and u.source_key = '47_Station_7.4_The_Complaint_and_the_Apology' and a.source_key = 'exam' and q.source_key = 'q-0'), 'option-0', 0, 'Go straight to it, with one breath — “something went wrong with your medication last night, and I’ve come to tell you exactly what” — then the fact.', null)
  on conflict (question_id, source_key) do nothing;
  insert into public.answer_options (question_id, source_key, sort_order, option_text, feedback)
