  insert into public.assessment_questions (assessment_id, question_kind_id, source_key, sort_order, is_critical, critical_label, stem, explanation)
  values ((select a.id from public.assessments a join public.learning_units u on u.id = a.unit_id where u.release_id = v_release_id and u.source_key = '47_Station_7.4_The_Complaint_and_the_Apology' and a.source_key = 'exam'), (select id from public.question_kinds where key = 'single_choice'), 'q-1', 1, true, 'the error, told plainly', '2 · The sentence itself. What does he hear?', 'The error, told plainly — the critical decision, and the whole grammar of the station in one sentence: the fact in plain words, active voice, named as an error and owned as ours. ‘A discrepancy we’re reviewing’ is the fog in an incident report’s clothing — he is left knowing something happened and nothing about what, which is the exact architecture of a cover-up. And ‘you may have received … nothing dangerous’ pre-shrinks the truth before he’s even holding it: the minimising disclosure is the version formal complaints are built from, because the patient later learns the fuller story and re-reads every soft word as spin. Plain, whole, his by right.')
  on conflict (assessment_id, source_key) do nothing;
  insert into public.answer_options (question_id, source_key, sort_order, option_text, feedback)
